const n={type:"ranks"},i={type:"ranks"},h={ante:{ru:["Анте","Небольшая обязательная ставка со всех игроков перед раздачей. Банки с первой улицы крупнее, играть становится выгоднее с более широким диапазоном рук."],en:["Ante","A small forced bet from every player before the deal. Pots are bigger from the start, so playing more hands pays off."]},bomb:{ru:["Bomb Pot","Специальная раздача: все за столом вносят одинаковую ставку, префлоп пропускается и сразу открывается флоп. Обычно случается раз в N рук и делает игру заметно экшеновее."],en:["Bomb Pot","A special hand: everyone posts the same amount, preflop is skipped and the flop is dealt straight away. Usually every N hands — adds a lot of action."]},double:{ru:["Двойная доска (Double Board)","Раздаются два борда одновременно, банк делится пополам: половину забирает лучшая рука на первой доске, половину — на второй. Можно выиграть «на одной доске» и не проиграть весь банк."],en:["Double Board","Two boards are dealt at once and the pot is split: half to the best hand on each board. You can win one board and save half the pot."]},rim:{ru:["Run it Multi-Times","Когда игроки в олл-ине до ривера, оставшиеся карты можно раздать два-три раза и разделить банк по результатам. Дисперсия ниже — меньше «обидных» проигрышей с лучшей рукой."],en:["Run it Multi-Times","When players are all-in before the river, the remaining cards can be dealt two or three times and the pot split by result. Lower variance, fewer bad beats."]},vpip:{ru:["Требование VPIP","Стол требует, чтобы игрок добровольно входил в банк в определённом проценте раздач. Так за столом не задерживаются те, кто только «сидит и ждёт»."],en:["VPIP requirement","The table requires each player to voluntarily put chips in a minimum share of hands, so nobody just sits and waits."]},gps:{ru:["Ограничение GPS & IP","Игроки с одного IP-адреса или находящиеся рядом по геолокации не могут сесть за один стол. Защита от сговора. В закрытом клубе MOJO : ALLIN этого ограничения нет."],en:["GPS & IP restriction","Players on the same IP or located close to each other cannot sit at one table — protection against collusion. The private MOJO : ALLIN club has no such restriction."]},bbmax:{ru:["10BB / 20BB / 50BB / 60BB Max","Варианты столов с ограниченной максимальной закупкой — например, не больше 20 больших блайндов. Игра на коротких стеках: больше олл-инов на префлопе и флопе, решения проще и быстрее."],en:["10BB / 20BB / 50BB / 60BB Max","Tables with a capped buy-in — e.g. at most 20 big blinds. Short-stack play: more all-ins preflop and on the flop, simpler and faster decisions."]}};function a(o,s){return[{type:"h2",text:o==="ru"?"Настройки столов в клубе":"Table settings in the club"},{type:"p",text:o==="ru"?"В лобби у каждого стола есть пометки. Вот что они значат:":"Every table in the lobby carries tags. Here is what they mean:"},{type:"table",head:o==="ru"?["Настройка","Что это значит"]:["Setting","What it means"],rows:s.map(t=>[`**${h[t][o][0]}**`,h[t][o][1]])}]}const r={type:"actions",items:[["Чек","Пропустить ход без ставки. Можно, только если в этом круге ещё никто не ставил."],["Бет","Первая ставка в круге торговли."],["Колл","Уравнять текущую ставку соперника."],["Рейз","Повысить ставку соперника. Повторный рейз называют 3-бетом, следующий — 4-бетом."],["Фолд","Сбросить карты и выйти из раздачи."],["Олл-ин","Поставить все свои фишки. Если у соперника больше, лишняя часть уходит в сайд-пот."]]},l={type:"actions",items:[["Check","Pass without betting. Only possible if nobody has bet in this round."],["Bet","The first bet in a betting round."],["Call","Match the opponent’s current bet."],["Raise","Increase the opponent’s bet. A re-raise is a 3-bet, the next one a 4-bet."],["Fold","Throw your cards away and leave the hand."],["All-in","Put all your chips in. If the opponent has more, the excess goes to a side pot."]]};function e(o,s){const t=o==="ru";return{actions:[{type:"h2",text:t?"Действия за столом":"Actions at the table"},{type:"p",text:t?`Действия в ${s} те же, что в холдеме. Разница одна: поставить или повысить можно не больше размера банка.`:`The actions in ${s} are the same as in Hold’em. The one difference: you can bet or raise at most the size of the pot.`},t?r:l],pot:[{type:"h2",text:t?"Как считается пот-лимит":"How pot-limit is counted"},{type:"p",text:t?"Максимальная ставка равна банку. Чтобы сделать максимальный рейз, сначала уравняйте ставку соперника, а затем добавьте весь получившийся банк. Подставьте свои цифры:":"The maximum bet equals the pot. For a maximum raise, first call the opponent’s bet, then add the whole resulting pot. Try your own numbers:"},{type:"potcalc"}],positions:[{type:"h2",text:t?"Позиции за столом":"Positions at the table"},{type:"p",text:t?"Позиция определяет, в каком порядке вы ходите. Чем позже ход, тем больше вы знаете о решениях соперников. В Омахе это особенно важно: банки растут быстро, и решение без информации стоит дороже. Нажмите на место за столом, чтобы прочитать о нём.":"Your position decides when you act. The later you act, the more you know about your opponents’ decisions. In Omaha this matters even more: pots grow fast and a decision without information costs more. Tap a seat to read about it."},{type:"positions"}]}}const d=[{slug:"nlh",format:"No Limit Holdem",shot:"/images/tables/nlh.webp",clubs:"both",ru:{menu:"Безлимитный холдем (NLH)",menuDesc:"Самая популярная игра: 2 карты на руках, ставки без ограничений",title:"Безлимитный холдем (NLH): правила и игра в клубе",subtitle:"Техасский холдем без лимита — правила раздачи, комбинации, порядок ставок и чем отличается игра в клубе ClubGG. С примерами и советами для старта.",facts:[["Карт на руках","2"],["Общих карт","5"],["Ставки","No-Limit"],["Игроков за столом","2–9"]],sections:[{type:"p",text:"**No-Limit Hold’em (NLH)** — техасский холдем без ограничения ставок, самая популярная разновидность покера в мире. Каждый игрок получает **две закрытые карты**, на стол выкладываются **пять общих**, и побеждает лучшая комбинация из пяти карт, собранная из этих семи. «Без лимита» значит, что в любой момент можно поставить весь стек — олл-ин."},{type:"h2",text:"История техасского холдема"},{type:"p",text:"Холдем появился в начале XX века в Техасе — местом рождения игры официально считается город Робстаун. В 1967 году техасские игроки привезли его в Лас-Вегас, и уже с 1971 года главный турнир World Series of Poker разыгрывается именно в безлимитный холдем. Настоящий бум случился в 2003-м, когда любитель Крис Манимейкер выиграл Main Event, попав туда через онлайн-сателлит. С тех пор NLH — стандарт и в живом, и в онлайн-покере."},{type:"timeline",items:[["1900-е","Холдем появляется в Техасе. Родиной игры считают город Робстаун."],["1967","Техасские игроки привозят холдем в Лас-Вегас."],["1971","Главный турнир World Series of Poker начинают разыгрывать в безлимитный холдем."],["2003","Любитель Крис Манимейкер выигрывает Main Event через онлайн-сателлит, и начинается покерный бум."]]},{type:"h2",text:"Лимитный, пот-лимитный и безлимитный холдем"},{type:"p",text:"Правила раздачи одинаковы, различается только размер ставок:"},{type:"table",head:["Структура","Сколько можно поставить","Особенность"],rows:[["**Limit (FL)**","Фиксированная ставка: на префлопе и флопе — малый шаг, на тёрне и ривере — двойной","Медленная математическая игра, сейчас встречается редко"],["**Pot-Limit (PL)**","Не больше текущего размера банка","Стандарт для Омахи"],["**No-Limit (NL)**","Любую сумму вплоть до всего стека (олл-ин)","Самый популярный формат — именно он идёт в клубе"]]},{type:"h2",text:"Цель игры"},{type:"p",text:"Выиграть банк: либо собрать лучшую пятикарточную комбинацию из своих двух карт и пяти общих к шоудауну, либо ставками заставить всех соперников сбросить карты раньше. Играют стандартной колодой из 52 карт, за столом от 2 до 9 человек."},{type:"h2",text:"Как проходит раздача"},{type:"ol",items:["**Блайнды.** Два игрока слева от баттона ставят обязательные ставки: малый (SB) и большой блайнд (BB). Например, на лимите 0.10/0.20 — 0.10 и 0.20 фишки.","**Префлоп.** Каждый получает две карты. Торговля начинается с игрока слева от большого блайнда: фолд, колл или рейз.","**Флоп.** Открываются три общие карты, второй круг торговли — теперь первым ходит ближайший к баттону активный игрок слева.","**Тёрн.** Четвёртая общая карта и третий круг торговли.","**Ривер.** Пятая карта и последний круг ставок.","**Шоудаун.** Оставшиеся игроки открывают карты; лучшая пятикарточная комбинация забирает банк. Можно использовать обе, одну или ни одной своей карты."]},{type:"streets",hole:["A♠","K♥"],board:["K♣","7♦","2♠","Q♥","10♣"],opp:["Q♠","J♠"],notes:["У вас A♠K♥ — одна из сильнейших стартовых рук. С ней обычно открывают торговлю рейзом.","Флоп K♣ 7♦ 2♠ даёт **верхнюю пару с лучшим кикером**. Доска «сухая»: дро на флеш и стрит почти нет, и вы впереди большинства рук.","Q♥ на тёрне вашу руку не меняет, но соперник с K-Q теперь собрал две пары. Крупная ставка против вас — повод задуматься.","10♣ на ривере: A-K-Q-10 похоже на стрит, но не хватает валета. Итог — **пара королей с кикером туз**.","Соперник показывает Q♠J♠: пара дам. Ваша пара королей старше, банк ваш."]},{type:"h2",text:"Действия за столом"},r,{type:"h2",text:"Старшинство комбинаций"},{type:"p",text:"Комбинации от старшей к младшей. Если у двух игроков одинаковая комбинация, решает старшинство карт, а затем кикер — старшая карта, не входящая в комбинацию."},n,{type:"h2",text:"Позиция — главное в холдеме"},{type:"p",text:"Баттон (BTN) ходит последним на всех улицах после флопа и видит решения соперников раньше своего. Поэтому с поздних позиций (баттон, катофф) можно играть заметно больше рук, а с ранних (UTG) — только сильные. Это правило работает на любом лимите и сильнее всего влияет на результат новичка."},{type:"positions"},{type:"h2",text:"Термины техасского холдема"},{type:"glossary",items:[["Карманные карты","Две закрытые карты, которые получает каждый игрок."],["Борд","Общие открытые карты в центре стола — флоп, тёрн и ривер."],["Кикер","Старшая карта, не входящая в комбинацию; решает при равных руках."],["Натсы","Лучшая возможная рука на текущем борде."],["Дро","Незаконченная рука, которой не хватает одной карты до стрита или флеша."],["Сет","Тройка, собранная из карманной пары и одной карты борда."],["Лимп","Вход в банк простым коллом большого блайнда без рейза."],["Стрэддл","Добровольная «слепая» ставка в два больших блайнда до раздачи."],["Сайд-пот","Отдельный банк, в котором участвуют только игроки с большими стеками, когда кто-то пошёл олл-ин на меньшую сумму."]]},{type:"h2",text:"Советы для старта"},{type:"ul",items:["Начните с узкого диапазона: пары от 77, AK–AT, KQ, одномастные тузы и коннекторы с поздних позиций.","Входите в банк рейзом, а не коллом (лимпом) — так вы забираете инициативу.","Ставьте на флопе, если флоп подходит вашей руке или «пугает» соперника, но не на каждой доске подряд.","Следите за размером стека: на столах 10BB/20BB Max игра сводится к олл-инам, на 100 ББ — к постфлоп-решениям.","Не отыгрывайтесь после крупного проигрыша — сделайте паузу."]},...a("ru",["ante","bomb","double","rim","vpip","gps","bbmax"]),{type:"h2",text:"Где играть NLH в клубах MOJO"},{type:"p",text:"Холдем идёт в обоих клубах: в [MOJO : MU](/clubs/mojo-massiv) — сотни столов союза круглосуточно на лимитах от 0.10/0.20 до 5/10, в [MOJO : ALLIN](/clubs/mojo-allin) — спокойные столы с проверенным составом и без ограничений по GPS. Чтобы сесть за стол, [скачайте ClubGG](/download), [создайте аккаунт](/create-account) и [вступите в клуб](/join)."}],faq:[{q:"Чем No-Limit отличается от Pot-Limit?",a:"В No-Limit можно поставить весь стек в любой момент. В Pot-Limit (как в Омахе) максимальная ставка ограничена размером банка."},{q:"Можно ли использовать только одну свою карту?",a:"Да. В холдеме лучшая комбинация собирается из любых пяти карт из семи — можно взять одну свою карту или даже сыграть «бордом»."},{q:"Что такое кикер?",a:"Старшая карта, не входящая в комбинацию. При одинаковой паре (например, тузы) выигрывает тот, у кого кикер выше."},{q:"Какие лимиты есть в клубе?",a:"От 0.10/0.20 до 5/10. Для старта подойдут 0.10/0.20 и 0.25/0.50."},{q:"Что такое Bomb Pot в холдеме?",a:"Раздача, в которой все вносят одинаковую ставку, префлоп пропускается и сразу открывается флоп."}]},en:{menu:"No-Limit Hold’em (NLH)",menuDesc:"The most popular game: 2 hole cards, no betting limit",title:"No-Limit Hold’em (NLH): rules and playing in the club",subtitle:"Texas Hold’em without a betting cap — how a hand plays, hand rankings, betting order and what is different in a ClubGG club. With examples and starter tips.",facts:[["Hole cards","2"],["Board cards","5"],["Betting","No-Limit"],["Players","2–9"]],sections:[{type:"p",text:"**No-Limit Hold’em (NLH)** is Texas Hold’em with no cap on bets — the most popular poker game in the world. Each player gets **two hole cards**, **five community cards** are dealt, and the best five-card hand made from those seven wins. “No-Limit” means you can bet your whole stack at any time — all-in."},{type:"h2",text:"History of Texas Hold’em"},{type:"p",text:"Hold’em appeared in early 20th-century Texas — the town of Robstown is officially recognised as its birthplace. Texan players brought it to Las Vegas in 1967, and since 1971 the World Series of Poker Main Event has been played as No-Limit Hold’em. The real boom came in 2003, when amateur Chris Moneymaker won the Main Event after qualifying through an online satellite. Since then NLH has been the standard both live and online."},{type:"timeline",items:[["1900s","Hold’em appears in Texas. Robstown is recognised as its birthplace."],["1967","Texan players bring Hold’em to Las Vegas."],["1971","The World Series of Poker Main Event switches to No-Limit Hold’em."],["2003","Amateur Chris Moneymaker wins the Main Event via an online satellite and the poker boom begins."]]},{type:"h2",text:"Limit, Pot-Limit and No-Limit Hold’em"},{type:"p",text:"The hand plays the same way; only the bet size differs:"},{type:"table",head:["Structure","How much you can bet","Notes"],rows:[["**Limit (FL)**","Fixed bets: a small step preflop and on the flop, double on the turn and river","Slow, mathematical, rarely played today"],["**Pot-Limit (PL)**","Up to the current size of the pot","The standard for Omaha"],["**No-Limit (NL)**","Any amount up to your whole stack (all-in)","The most popular format — the one played in the club"]]},{type:"h2",text:"The goal"},{type:"p",text:"Win the pot: either hold the best five-card hand from your two cards and the five on board at showdown, or make every opponent fold earlier. A standard 52-card deck is used, with 2 to 9 players at a table."},{type:"h2",text:"How a hand plays"},{type:"ol",items:["**Blinds.** The two players left of the button post forced bets: small blind (SB) and big blind (BB) — e.g. 0.10 and 0.20 chips at 0.10/0.20.","**Preflop.** Everyone gets two cards. Action starts left of the big blind: fold, call or raise.","**Flop.** Three community cards and the second betting round; the first active player left of the button acts first.","**Turn.** The fourth card and the third betting round.","**River.** The fifth card and the final betting round.","**Showdown.** Remaining players show; the best five-card hand wins. You may use both, one or none of your hole cards."]},{type:"streets",hole:["A♠","K♥"],board:["K♣","7♦","2♠","Q♥","10♣"],opp:["Q♠","J♠"],notes:["You hold A♠K♥, one of the strongest starting hands. It is usually opened with a raise.","The K♣ 7♦ 2♠ flop gives you **top pair with the best kicker**. The board is dry, with almost no flush or straight draws, and you are ahead of most hands.","The Q♥ turn does not change your hand, but an opponent with K-Q now has two pair. A big bet against you deserves some thought.","The 10♣ river: A-K-Q-10 looks like a straight, but the jack is missing. Final hand: **a pair of kings with an ace kicker**.","The opponent shows Q♠J♠: a pair of queens. Your pair of kings is higher, so the pot is yours."]},{type:"h2",text:"Actions at the table"},l,{type:"h2",text:"Hand rankings"},{type:"p",text:"From strongest to weakest. With equal hands the card ranks decide, then the kicker — the highest card outside the combination."},i,{type:"h2",text:"Position matters most"},{type:"p",text:"The button acts last on every street after the flop and sees opponents’ decisions first. From late positions (button, cutoff) you can play far more hands; from early ones (UTG) only strong hands. This one rule moves a beginner’s results more than anything else."},{type:"positions"},{type:"h2",text:"Texas Hold’em terms"},{type:"glossary",items:[["Hole cards","The two face-down cards each player receives."],["Board","The community cards in the middle — flop, turn and river."],["Kicker","The highest card outside the combination; breaks ties."],["Nuts","The best possible hand on the current board."],["Draw","An unfinished hand one card short of a straight or flush."],["Set","Three of a kind made with a pocket pair and one board card."],["Limp","Entering the pot by just calling the big blind."],["Straddle","A voluntary blind bet of two big blinds before the deal."],["Side pot","A separate pot for the bigger stacks when someone is all-in for less."]]},{type:"h2",text:"Starter tips"},{type:"ul",items:["Start tight: pairs 77+, AK–AT, KQ, suited aces and connectors from late position.","Enter pots with a raise, not a limp — take the initiative.","Bet the flop when it suits your hand or scares your opponent, not on every board.","Watch stack depth: 10BB/20BB Max tables are about all-ins, 100 BB play is about postflop decisions.","Do not chase losses after a big pot — take a break."]},...a("en",["ante","bomb","double","rim","vpip","gps","bbmax"]),{type:"h2",text:"Where to play NLH at MOJO"},{type:"p",text:"Hold’em runs in both clubs: [MOJO : MU](/clubs/mojo-massiv) has hundreds of union tables around the clock from 0.10/0.20 to 5/10, [MOJO : ALLIN](/clubs/mojo-allin) offers calm tables with a vetted roster and no GPS restriction. To sit down, [download ClubGG](/download), [create an account](/create-account) and [join the club](/join)."}],faq:[{q:"How is No-Limit different from Pot-Limit?",a:"In No-Limit you can bet your whole stack at any time. In Pot-Limit (as in Omaha) the maximum bet is the size of the pot."},{q:"Can I use only one of my hole cards?",a:"Yes. In Hold’em the best hand is any five of the seven cards — one hole card or even the board alone."},{q:"What is a kicker?",a:"The highest card outside the combination. With the same pair, the higher kicker wins."},{q:"Which stakes run in the club?",a:"From 0.10/0.20 to 5/10. 0.10/0.20 and 0.25/0.50 are good to start."},{q:"What is a Bomb Pot?",a:"A hand where everyone posts the same amount, preflop is skipped and the flop is dealt straight away."}]}},{slug:"plo4",format:"Pot Limit Omaha (PLO4)",shot:"/images/tables/plo4.webp",clubs:"both",ru:{menu:"Омаха PLO4",menuDesc:"4 карты на руках, пот-лимит: больше комбинаций и экшена",title:"Омаха PLO4: правила, комбинации и отличия от холдема",subtitle:"Пот-лимит Омаха на четыре карты — главное правило «2 + 3», как считается пот-лимит, типичные ошибки новичков и как играть Омаху в клубе.",facts:[["Карт на руках","4"],["Общих карт","5"],["Ставки","Pot-Limit"],["Используете","2 своих + 3 общих"]],sections:[{type:"p",text:"**Pot-Limit Omaha (PLO, PLO4)** — второй по популярности вид покера после холдема. Раздача устроена так же: блайнды, префлоп, флоп, тёрн, ривер. Отличий два, но они меняют всю игру: у каждого **четыре карты на руках**, а комбинацию нужно собирать **ровно из двух своих карт и ровно трёх общих**."},{type:"h2",text:"Главное правило Омахи: 2 + 3"},{type:"p",text:"Это правило чаще всего путает новичков, пришедших из холдема. Нельзя сыграть одной своей картой и четырьмя с борда, и нельзя взять три своих."},{type:"table",head:["Ситуация","Холдем","Омаха"],rows:[["На борде 4 червы, у вас одна черва","Флеш ✔","Нет флеша ✘ — нужны две червы на руках"],["На борде A-A-A-K-Q, у вас 7-2","Играете бордом","Нельзя сыграть бордом — используете 2 свои карты"],["У вас четыре туза","—","Только пара тузов: 2 своих + 3 с борда"],["Стрит на борде 9-8-7-6-5","У всех стрит","Стрит есть только у тех, кто дополняет его двумя картами"]]},{type:"h2",text:"Ход раздачи"},{type:"streets",hole:["A♠","K♠","J♥","10♥"],board:["K♥","Q♠","7♥","9♣","2♥"],opp:["Q♣","Q♦","9♠","8♠"],notes:["A♠K♠J♥10♥ — сильная рука для Омахи: две масти, пики и червы, и четыре связанные карты.","Флоп K♥ Q♠ 7♥ даёт пару королей, дро на флеш (J♥10♥ и две червы борда) и дро на стрит: валету с десяткой нужен туз или девятка.","9♣ закрывает стрит: J-10 с руки и K-Q-9 с борда дают **стрит до короля**.","2♥ — третья черва на борде. J♥10♥ с руки и K♥7♥2♥ с борда собирают **флеш**, а он старше стрита.","Соперник показывает Q♣Q♦: на флопе у него был сет дам. Но флеш старше сета, поэтому банк ваш."]},...e("ru","PLO4").actions,{type:"h2",text:"Как работает пот-лимит"},{type:"p",text:"Максимальная ставка — размер банка. Если вы делаете рейз, сначала мысленно уравниваете ставку соперника, а затем добавляете получившийся банк. Пример: в банке 10, соперник ставит 10. Вы можете поставить максимум: 10 (колл) + 30 (банк после колла) = **40**. В ClubGG кнопка «Pot» считает это автоматически."},{type:"potcalc"},{type:"h2",text:"Комбинации в Омахе"},{type:"p",text:"Старшинство комбинаций такое же, как в холдеме, но встречаются они гораздо чаще: из четырёх карт можно составить **6 разных пар карт**, поэтому стриты, флеши и фулл-хаусы на шоудауне — обычное дело. «Две пары» и «верхняя пара», сильные в холдеме, в Омахе часто проигрывают."},n,{type:"h2",text:"Кто выигрывает банк"},{type:"p",text:"На шоудауне каждый собирает лучшую руку из **ровно двух своих карт и трёх общих**. Нажмите на игрока, чтобы увидеть, какие карты он использует."},{type:"showdown",lo:!1,title:"Шоудаун в Омахе: правило 2 + 3",board:["K♥","Q♠","7♥","9♣","2♥"],players:[{name:"Игрок А",cards:["A♥","5♥","Q♣","8♦"]},{name:"Игрок Б",cards:["K♠","K♦","7♣","4♠"]},{name:"Игрок В",cards:["Q♥","J♣","10♣","3♦"]}],split:[{label:"Игрок А",pct:100,tone:"high"}]},{type:"p",text:"Игрок А собирает флеш: A♥5♥ с руки и K♥7♥2♥ с борда. У игрока В тоже есть черва, но только одна. В холдеме при трёх червах на столе это был бы флеш, а в Омахе нужны ровно две карты масти с руки, поэтому его лучшая рука — стрит до короля. Сет королей игрока Б проигрывает и стриту, и флешу."},...e("ru","PLO4").positions,{type:"h2",text:"Какие руки сильные в PLO4"},{type:"ul",items:["**Двойные одномастные (double-suited)** — две пары мастей, например A♠K♠J♥10♥: шансы на два разных флеша.","**Связанные руки (rundowns)** — карты подряд, например J-10-9-8: много вариантов стрита.","**Пары с поддержкой** — A-A-K-Q одномастные; пара тузов сама по себе в Омахе не так сильна, как в холдеме.","Избегайте «дэнглеров» — одной карты, никак не связанной с остальными тремя."]},{type:"h2",text:"Частые ошибки новичков"},{type:"ul",items:["Играть флеш «одной картой масти» — в Омахе его не бывает.","Ставить олл-ин с непервым флешем или стритом: в Омахе важны **натсы** — лучшая возможная рука на этой доске.","Переоценивать пару тузов без поддержки.","Играть слишком много рук с ранних позиций: позиция в Омахе важна ещё сильнее, чем в холдеме."]},{type:"h2",text:"Термины Омахи"},{type:"glossary",items:[["Правило 2 + 3","Комбинация собирается ровно из двух карманных и трёх общих карт."],["Дабл-сьютед","Рука с двумя парами одномастных карт — два разных флеш-дро."],["Рандаун","Связанные карты подряд (J-10-9-8) — много вариантов стрита."],["Дэнглер","Карта, никак не связанная с остальными в руке. Снижает силу руки."],["Натсы","Лучшая возможная рука на доске. В Омахе выигрывают чаще всего именно натсы."],["Блокер","Ваша карта, которая не даёт сопернику собрать определённую руку, — например, туз масти против натсового флеша."],["Pot","Кнопка максимальной ставки размером в банк."]]},...a("ru",["ante","bomb","double","rim","vpip","gps","bbmax"]),{type:"h2",text:"Где играть PLO4 в клубах MOJO"},{type:"p",text:"Омаха идёт в обоих клубах на лимитах от 0.25/0.50 до 5/10. В [MOJO : MU](/clubs/mojo-massiv) — много столов союза с Bomb Pot и Double Board, в [MOJO : ALLIN](/clubs/mojo-allin) — спокойная игра без GPS-ограничений. Если только переходите с холдема, сначала прочитайте про [PLO5](/games/plo5) и [PLO6](/games/plo6) — там те же правила, но ещё больше карт."}],faq:[{q:"Сколько своих карт нужно использовать в Омахе?",a:"Ровно две из четырёх на руках и ровно три из пяти общих."},{q:"Можно ли в Омахе сыграть бордом?",a:"Нет. Даже если на борде стрит или флеш, в комбинации обязательно участвуют две ваши карты."},{q:"Что значит Pot-Limit?",a:"Максимальная ставка или рейз ограничены размером банка с учётом вашего колла."},{q:"Пара тузов в Омахе — сильная рука?",a:"Хорошая на префлопе, если поддержана мастями и связанными картами, но после флопа часто проигрывает стритам и флешам."},{q:"Чем PLO4 отличается от PLO5?",a:"Количеством карт на руках: 4 против 5. Правило «2 + 3» одинаковое, но в PLO5 комбинаций больше и руки ближе по силе."}]},en:{menu:"Omaha PLO4",menuDesc:"4 hole cards, pot-limit: more hands and more action",title:"Omaha PLO4: rules, hands and how it differs from Hold’em",subtitle:"Four-card Pot-Limit Omaha — the key “2 + 3” rule, how pot-limit is counted, typical beginner mistakes and playing Omaha in the club.",facts:[["Hole cards","4"],["Board cards","5"],["Betting","Pot-Limit"],["You use","2 hole + 3 board"]],sections:[{type:"p",text:"**Pot-Limit Omaha (PLO, PLO4)** is the second most popular poker game after Hold’em. The hand flows the same way — blinds, preflop, flop, turn, river — with two differences that change everything: you get **four hole cards** and must make your hand from **exactly two of them and exactly three board cards**."},{type:"h2",text:"The key Omaha rule: 2 + 3"},{type:"p",text:"This is what trips up Hold’em players most. You cannot play one hole card with four from the board, and you cannot use three of your own."},{type:"table",head:["Situation","Hold’em","Omaha"],rows:[["Four hearts on board, you hold one heart","Flush ✔","No flush ✘ — you need two hearts in hand"],["Board A-A-A-K-Q, you hold 7-2","You play the board","Cannot play the board — two hole cards must play"],["You hold four aces","—","Just a pair of aces: 2 hole + 3 board"],["Straight on board 9-8-7-6-5","Everyone has it","Only players who complete it with two hole cards"]]},{type:"h2",text:"How a hand plays"},{type:"streets",hole:["A♠","K♠","J♥","10♥"],board:["K♥","Q♠","7♥","9♣","2♥"],opp:["Q♣","Q♦","9♠","8♠"],notes:["A♠K♠J♥10♥ is a strong Omaha hand: two suits, spades and hearts, and four connected cards.","The K♥ Q♠ 7♥ flop gives you a pair of kings, a flush draw (J♥10♥ with two hearts on board) and a straight draw: the jack and ten need an ace or a nine.","The 9♣ completes the straight: J-10 from your hand and K-Q-9 from the board make **a king-high straight**.","The 2♥ is the third heart on board. J♥10♥ from your hand and K♥7♥2♥ from the board make **a flush**, which beats the straight.","The opponent shows Q♣Q♦: he flopped a set of queens. But a flush beats a set, so the pot is yours."]},...e("en","PLO4").actions,{type:"h2",text:"How pot-limit works"},{type:"p",text:"The maximum bet is the size of the pot. To raise, first count your call, then add the resulting pot. Example: pot 10, opponent bets 10. Your maximum raise is 10 (call) + 30 (pot after the call) = **40**. The “Pot” button in ClubGG does this for you."},{type:"potcalc"},{type:"h2",text:"Hands in Omaha"},{type:"p",text:"The rankings are the same as in Hold’em, but strong hands come up far more often: four hole cards make **6 different two-card combinations**, so straights, flushes and full houses at showdown are routine. Two pair and top pair, strong in Hold’em, often lose in Omaha."},i,{type:"h2",text:"Who wins the pot"},{type:"p",text:"At showdown everyone makes their best hand from **exactly two hole cards and three board cards**. Tap a player to see which cards they use."},{type:"showdown",lo:!1,title:"An Omaha showdown: the 2 + 3 rule",board:["K♥","Q♠","7♥","9♣","2♥"],players:[{name:"Player A",cards:["A♥","5♥","Q♣","8♦"]},{name:"Player B",cards:["K♠","K♦","7♣","4♠"]},{name:"Player C",cards:["Q♥","J♣","10♣","3♦"]}],split:[{label:"Player A",pct:100,tone:"high"}]},{type:"p",text:"Player A makes a flush: A♥5♥ from the hand and K♥7♥2♥ from the board. Player C also holds a heart, but only one. In Hold’em three hearts on board would give him a flush; in Omaha you need exactly two suited cards from your hand, so his best hand is a king-high straight. Player B’s set of kings loses to both."},...e("en","PLO4").positions,{type:"h2",text:"Strong PLO4 starting hands"},{type:"ul",items:["**Double-suited** — two suits in pairs, e.g. A♠K♠J♥10♥: two different flush draws.","**Rundowns** — connected cards like J-10-9-8: many straight possibilities.","**Supported pairs** — A-A-K-Q suited; a bare pair of aces is much weaker than in Hold’em.","Avoid “danglers” — one card unrelated to the other three."]},{type:"h2",text:"Common beginner mistakes"},{type:"ul",items:["Playing a flush with one suited card — it does not exist in Omaha.","Going all-in with a non-nut flush or straight: in Omaha the **nuts** — the best possible hand on that board — matter.","Overvaluing an unsupported pair of aces.","Playing too many hands from early position: position matters even more than in Hold’em."]},{type:"h2",text:"Omaha terms"},{type:"glossary",items:[["2 + 3 rule","Your hand uses exactly two hole cards and three board cards."],["Double-suited","Two pairs of suited cards — two different flush draws."],["Rundown","Connected cards (J-10-9-8) — many straight possibilities."],["Dangler","A card unrelated to the rest of the hand; weakens it."],["Nuts","The best possible hand on the board. In Omaha the nuts usually win."],["Blocker","A card that stops an opponent from holding a hand — e.g. the ace of a suit against the nut flush."],["Pot","The button for a pot-sized bet."]]},...a("en",["ante","bomb","double","rim","vpip","gps","bbmax"]),{type:"h2",text:"Where to play PLO4 at MOJO"},{type:"p",text:"Omaha runs in both clubs from 0.25/0.50 to 5/10. [MOJO : MU](/clubs/mojo-massiv) has many union tables with Bomb Pot and Double Board, [MOJO : ALLIN](/clubs/mojo-allin) a calm game without GPS restrictions. Moving up from four cards? Read about [PLO5](/games/plo5) and [PLO6](/games/plo6)."}],faq:[{q:"How many hole cards must I use in Omaha?",a:"Exactly two of your four and exactly three of the five board cards."},{q:"Can I play the board in Omaha?",a:"No. Even with a straight or flush on board, two of your hole cards must play."},{q:"What does Pot-Limit mean?",a:"The maximum bet or raise is the size of the pot including your call."},{q:"Are aces strong in Omaha?",a:"Good preflop when supported by suits and connected cards, but they often lose to straights and flushes after the flop."},{q:"How is PLO4 different from PLO5?",a:"Four hole cards versus five. The “2 + 3” rule is the same, but PLO5 has more combinations and closer equities."}]}},{slug:"plo5",format:"PLO5",shot:"/images/tables/plo5.webp",clubs:"both",ru:{menu:"Омаха PLO5",menuDesc:"5 карт на руках: 10 комбинаций, частые Bomb Pot",title:"Омаха PLO5 (пятикарточная): правила и стратегия",subtitle:"Пятикарточная пот-лимит Омаха — чем отличается от PLO4, сколько комбинаций даёт рука, какие стартовые руки играть и как устроены столы PLO5 в клубе.",facts:[["Карт на руках","5"],["Комбинаций из руки","10"],["Ставки","Pot-Limit"],["Используете","2 своих + 3 общих"]],sections:[{type:"p",text:"**PLO5 (Five-Card Omaha)** — Омаха, в которой каждый получает **пять карт**. Всё остальное как в [PLO4](/games/plo4): пот-лимит, пять общих карт и строгое правило — комбинация собирается **ровно из двух своих и трёх общих карт**. Пятая карта кажется мелочью, но она заметно меняет игру."},{type:"h2",text:"Чем PLO5 отличается от PLO4"},{type:"table",head:["","PLO4","PLO5"],rows:[["Карт на руках","4","5"],["Пар карт для комбинации","6","**10**"],["Типичная выигрышная рука","Стрит / флеш","Чаще натсовый флеш, фулл-хаус"],["Разброс эквити на префлопе","Средний","Руки ещё ближе по силе"],["Игроков за столом","до 9","обычно 6"]]},{type:"p",text:"Из пяти карт можно выбрать **10 разных пар** против 6 в четырёхкарточной Омахе. Значит, у соперников чаще собираются сильные руки, и «второй по силе» флеш или стрит проигрывает ещё чаще."},{type:"h2",text:"Ход раздачи"},{type:"streets",hole:["A♠","K♠","Q♥","J♥","10♦"],board:["K♥","Q♠","7♥","9♣","2♥"],opp:["K♦","K♣","7♣","6♦","5♠"],notes:["Пять карт на руках — это 10 разных пар для комбинаций. Здесь есть туз с королём пик, дама с валетом червей и длинная связка A-K-Q-J-10.","Флоп K♥ Q♠ 7♥ даёт **две пары, короли и дамы**: K-Q с руки. В запасе дро на флеш червей и дро на стрит.","9♣: J-10 с руки и K-Q-9 с борда дают **стрит до короля**. Две пары уже не лучшая ваша рука.","2♥ — третья черва. Q♥J♥ с руки и K♥7♥2♥ с борда собирают **флеш до короля**.","Соперник показывает K♦K♣ и сет королей с флопа. Флеш до короля старше, банк ваш."]},{type:"h2",text:"Как играть PLO5: базовые принципы"},{type:"ul",items:["**Играйте на натсы.** Флеш с тузом масти, верхний стрит, верхний фулл-хаус — то, ради чего стоит идти до конца.","**Ищите «работающие» пять карт.** Лучшие руки — связанные и одномастные, где все карты участвуют: например A♠K♠Q♥J♥10♦.","**Не переоценивайте пары.** Пара тузов в пяти картах — лишь одна из десяти комбинаций.","**Аккуратнее с блефом.** Чем больше карт, тем чаще у соперника есть хоть что-то, с чем он уравняет.","**Позиция решает.** Последнее слово на тёрне и ривере в PLO5 особенно ценно."]},{type:"h2",text:"Bomb Pot в PLO5"},{type:"p",text:"Пятикарточная Омаха — основной формат для Bomb Pot: раздача, в которой все вносят одинаковую ставку и сразу видят флоп. С пятью картами почти каждый флоп кому-то подходит, поэтому такие банки крупные и экшеновые. На скриншоте выше — как раз Bomb Pot за столом PLO5 в ClubGG."},{type:"h2",text:"Старшинство комбинаций"},n,...e("ru","PLO5").positions,...e("ru","PLO5").pot,{type:"h2",text:"Термины Омахи"},{type:"glossary",items:[["Правило 2 + 3","Комбинация собирается ровно из двух карманных и трёх общих карт."],["Дабл-сьютед","Рука с двумя парами одномастных карт — два разных флеш-дро."],["Рандаун","Связанные карты подряд (J-10-9-8) — много вариантов стрита."],["Дэнглер","Карта, никак не связанная с остальными в руке. Снижает силу руки."],["Натсы","Лучшая возможная рука на доске. В Омахе выигрывают чаще всего именно натсы."],["Блокер","Ваша карта, которая не даёт сопернику собрать определённую руку, — например, туз масти против натсового флеша."],["Pot","Кнопка максимальной ставки размером в банк."]]},...a("ru",["ante","bomb","rim","vpip","gps","bbmax"]),{type:"h2",text:"Где играть PLO5 в клубах MOJO"},{type:"p",text:"Столы PLO5 идут в обоих клубах на лимитах от 0.25/0.50 до 5/10. Есть варианты с ограничением закупки 20BB и 50BB Max. Перед первой игрой убедитесь, что уверенно знаете правила [PLO4](/games/plo4) — пятикарточная Омаха строится на них. Ещё больше экшена — в [PLO6](/games/plo6)."}],faq:[{q:"Сколько карт использовать в PLO5?",a:"Как и в любой Омахе — ровно две своих и ровно три общих."},{q:"Сколько комбинаций даёт рука из пяти карт?",a:"10 разных пар карт (против 6 в PLO4 и 1 в холдеме)."},{q:"Почему в PLO5 обычно 6 мест за столом?",a:"Чтобы хватило колоды: 9 игроков × 5 карт + 5 общих = 50 карт — на грани колоды, поэтому PLO5 играют 6-max."},{q:"Что лучше для новичка: PLO4 или PLO5?",a:"Начните с PLO4 — правила те же, но решения проще. В PLO5 переходите, когда уверенно оцениваете натсы."},{q:"Что такое Bomb Pot в PLO5?",a:"Раздача, где все вносят одинаковую ставку и игра начинается сразу с флопа."}]},en:{menu:"Omaha PLO5",menuDesc:"5 hole cards: 10 combinations, frequent Bomb Pots",title:"PLO5 (Five-Card Omaha): rules and strategy",subtitle:"Five-card Pot-Limit Omaha — how it differs from PLO4, how many combinations a hand gives, which starting hands to play and how PLO5 tables work in the club.",facts:[["Hole cards","5"],["Two-card combos","10"],["Betting","Pot-Limit"],["You use","2 hole + 3 board"]],sections:[{type:"p",text:"**PLO5 (Five-Card Omaha)** gives every player **five hole cards**. Everything else is as in [PLO4](/games/plo4): pot-limit, five board cards and the strict rule — your hand uses **exactly two hole cards and three board cards**. One extra card sounds minor, but it changes the game noticeably."},{type:"h2",text:"PLO5 vs PLO4"},{type:"table",head:["","PLO4","PLO5"],rows:[["Hole cards","4","5"],["Two-card combinations","6","**10**"],["Typical winning hand","Straight / flush","More often a nut flush or full house"],["Preflop equity spread","Medium","Even closer"],["Seats","up to 9","usually 6"]]},{type:"p",text:"Five cards give **10 different pairs** versus 6 in four-card Omaha, so opponents hit strong hands more often and second-best flushes or straights lose even more."},{type:"h2",text:"How a hand plays"},{type:"streets",hole:["A♠","K♠","Q♥","J♥","10♦"],board:["K♥","Q♠","7♥","9♣","2♥"],opp:["K♦","K♣","7♣","6♦","5♠"],notes:["Five hole cards give 10 different two-card pairs. This hand has the ace and king of spades, the queen and jack of hearts and a long A-K-Q-J-10 rundown.","The K♥ Q♠ 7♥ flop gives you **two pair, kings and queens**, with K-Q from your hand. You also have a heart flush draw and a straight draw.","The 9♣: J-10 from your hand and K-Q-9 from the board make **a king-high straight**. Two pair is no longer your best hand.","The 2♥ is the third heart. Q♥J♥ from your hand and K♥7♥2♥ from the board make **a king-high flush**.","The opponent shows K♦K♣ and the set of kings he flopped. Your king-high flush is higher, so the pot is yours."]},{type:"h2",text:"Playing PLO5: the basics"},{type:"ul",items:["**Play for the nuts.** Ace-high flush, top straight, top full house — those are worth going to the end with.","**Look for five working cards.** The best hands are connected and suited with every card contributing, e.g. A♠K♠Q♥J♥10♦.","**Do not overvalue pairs.** A pair of aces is just one of ten combinations.","**Bluff less.** With more cards, opponents more often have something to call with.","**Position decides.** Acting last on the turn and river is especially valuable."]},{type:"h2",text:"Bomb Pots in PLO5"},{type:"p",text:"Five-card Omaha is the main Bomb Pot format: everyone posts the same amount and sees the flop straight away. With five cards nearly every flop hits someone, so these pots are big and full of action — the screenshot above is a Bomb Pot at a PLO5 table in ClubGG."},{type:"h2",text:"Hand rankings"},i,...e("en","PLO5").positions,...e("en","PLO5").pot,{type:"h2",text:"Omaha terms"},{type:"glossary",items:[["2 + 3 rule","Your hand uses exactly two hole cards and three board cards."],["Double-suited","Two pairs of suited cards — two different flush draws."],["Rundown","Connected cards (J-10-9-8) — many straight possibilities."],["Dangler","A card unrelated to the rest of the hand; weakens it."],["Nuts","The best possible hand on the board. In Omaha the nuts usually win."],["Blocker","A card that stops an opponent from holding a hand — e.g. the ace of a suit against the nut flush."],["Pot","The button for a pot-sized bet."]]},...a("en",["ante","bomb","rim","vpip","gps","bbmax"]),{type:"h2",text:"Where to play PLO5 at MOJO"},{type:"p",text:"PLO5 runs in both clubs from 0.25/0.50 to 5/10, including 20BB and 50BB Max tables. Make sure you know [PLO4](/games/plo4) well first — five-card Omaha builds on it. For even more action, try [PLO6](/games/plo6)."}],faq:[{q:"How many cards do I use in PLO5?",a:"As in any Omaha — exactly two hole cards and exactly three board cards."},{q:"How many combinations does a five-card hand give?",a:"10 different pairs (versus 6 in PLO4 and 1 in Hold’em)."},{q:"Why is PLO5 usually 6-max?",a:"Deck size: 9 players × 5 cards + 5 board = 50 cards, right at the limit, so PLO5 is dealt 6-handed."},{q:"PLO4 or PLO5 for a beginner?",a:"Start with PLO4 — same rules, simpler decisions. Move to PLO5 once you read the nuts confidently."},{q:"What is a Bomb Pot in PLO5?",a:"A hand where everyone posts the same amount and play starts on the flop."}]}},{slug:"plo6",format:"PLO6",shot:"/images/tables/plo6.webp",clubs:"both",ru:{menu:"Омаха PLO6",menuDesc:"6 карт на руках: 15 комбинаций и максимум экшена",title:"Омаха PLO6 (шестикарточная): правила и особенности",subtitle:"Шестикарточная пот-лимит Омаха — самая экшеновая версия Омахи. Правила, 15 комбинаций из руки, почему здесь выигрывают натсы и как устроены столы PLO6 в клубе.",facts:[["Карт на руках","6"],["Комбинаций из руки","15"],["Ставки","Pot-Limit"],["Используете","2 своих + 3 общих"]],sections:[{type:"p",text:"**PLO6 (Six-Card Omaha)** — Омаха, где у каждого **шесть карт на руках**. Правило то же, что в [PLO4](/games/plo4) и [PLO5](/games/plo5): **ровно две свои карты и три общие**. Из шести карт складывается 15 разных пар, поэтому на флопе почти у каждого есть дро или готовая рука — это самая «экшеновая» разновидность Омахи."},{type:"h2",text:"PLO4, PLO5 и PLO6 в цифрах"},{type:"table",head:["","PLO4","PLO5","PLO6"],rows:[["Карт на руках","4","5","6"],["Пар карт из руки","6","10","**15**"],["Мест за столом","до 9","обычно 6","обычно 6"],["Чем выигрывают","Стрит, флеш","Натсовый флеш, фулл-хаус","Почти всегда натсы"]]},{type:"h2",text:"Ход раздачи"},{type:"streets",hole:["A♠","K♠","Q♥","J♥","10♦","9♦"],board:["K♥","Q♠","7♥","9♣","2♥"],opp:["A♥","5♥","K♣","K♦","8♣","3♠"],notes:["Шесть карт на руках — это 15 разных пар для комбинаций. Рука связанная и сразу в трёх мастях: пики, червы и бубны.","Флоп K♥ Q♠ 7♥ даёт **две пары, короли и дамы**. В PLO6 у соперников часто есть такие же сильные руки, поэтому важны дро на натсы.","9♣: J-10 с руки и K-Q-9 с борда дают **стрит до короля**.","2♥ — третья черва. Q♥J♥ с руки и K♥7♥2♥ с борда собирают **флеш до короля**. Натсовый флеш здесь был бы у соперника с A♥ и ещё одной червой.","Соперник показывает A♥5♥ — натсовый флеш до туза. Ваш флеш до короля проигрывает. В PLO6 вторые по силе руки часто отдают банк."]},{type:"h2",text:"Особенности игры"},{type:"ul",items:["**Натсы — всё.** С шестью картами у кого-то почти наверняка есть лучшая рука; второй по силе флеш часто стоит сбросить.","**Мало блефа, много вэлью.** Соперникам есть чем уравнивать, поэтому ставьте с сильными руками и чаще чекайте без них.","**Ценность «блокеров».** Если у вас туз масти, у соперника не может быть натсового флеша этой масти — это помогает принимать решения на ривере.","**Run it Multi-Times.** Олл-ины в PLO6 часто идут с близкими шансами (55/45), поэтому раскладывать борд два-три раза — разумная страховка от дисперсии.","**Двойная доска.** Столы PLO6 с Double Board позволяют выиграть половину банка, даже если на одной доске проиграли."]},{type:"h2",text:"С каких рук входить"},{type:"p",text:"Хорошая рука в PLO6 — та, где большинство из шести карт работают вместе: две масти по две-три карты, связанные ранги, натсовые возможности (туз масти, верхние карты стрита). Пример сильной руки: **A♠K♠Q♥J♥10♦9♦** — три масти, длинная связка, натсовые флеш-дро. Слабые руки — разрозненные карты без мастей, с «дырами» в рангах."},{type:"h2",text:"Старшинство комбинаций"},n,...e("ru","PLO6").positions,...e("ru","PLO6").pot,{type:"h2",text:"Термины Омахи"},{type:"glossary",items:[["Правило 2 + 3","Комбинация собирается ровно из двух карманных и трёх общих карт."],["Дабл-сьютед","Рука с двумя парами одномастных карт — два разных флеш-дро."],["Рандаун","Связанные карты подряд (J-10-9-8) — много вариантов стрита."],["Дэнглер","Карта, никак не связанная с остальными в руке. Снижает силу руки."],["Натсы","Лучшая возможная рука на доске. В Омахе выигрывают чаще всего именно натсы."],["Блокер","Ваша карта, которая не даёт сопернику собрать определённую руку, — например, туз масти против натсового флеша."],["Pot","Кнопка максимальной ставки размером в банк."]]},...a("ru",["ante","double","rim","vpip","gps","bbmax"]),{type:"h2",text:"Где играть PLO6 в клубах MOJO"},{type:"p",text:"Столы PLO6 работают в обоих клубах на лимитах от 0.25/0.50 до 5/10, включая 10BB и 60BB Max и столы с двойной доской. Если любите экшен, но хотите разделить банк между хорошими «верхом» и «низом», посмотрите [Омаху Hi-Lo](/games/plo-hi-lo)."}],faq:[{q:"Сколько своих карт нужно в PLO6?",a:"Ровно две из шести на руках и ровно три общих."},{q:"Почему в PLO6 обычно 6 игроков?",a:"Колоды не хватит на большее: 7 игроков × 6 карт + 5 общих = 47 карт, при 8 игроках уже 53 — больше колоды."},{q:"Что такое натсы?",a:"Лучшая возможная рука на текущей доске. В PLO6 сильнейшие руки встречаются так часто, что выигрывают обычно именно натсы."},{q:"Чем помогает Run it Multi-Times?",a:"При олл-ине оставшиеся карты раздаются 2–3 раза, банк делится по результатам — меньше дисперсии."},{q:"Подходит ли PLO6 новичку?",a:"Лучше начать с PLO4: правила те же, но в PLO6 ошибки обходятся дороже из-за силы рук соперников."}]},en:{menu:"Omaha PLO6",menuDesc:"6 hole cards: 15 combinations and maximum action",title:"PLO6 (Six-Card Omaha): rules and features",subtitle:"Six-card Pot-Limit Omaha — the most action-packed Omaha. Rules, 15 combinations per hand, why the nuts win here and how PLO6 tables work in the club.",facts:[["Hole cards","6"],["Two-card combos","15"],["Betting","Pot-Limit"],["You use","2 hole + 3 board"]],sections:[{type:"p",text:"**PLO6 (Six-Card Omaha)** gives everyone **six hole cards**. The rule is the same as in [PLO4](/games/plo4) and [PLO5](/games/plo5): **exactly two hole cards and three board cards**. Six cards make 15 different pairs, so almost everyone has a draw or a made hand on the flop — the most action-packed Omaha there is."},{type:"h2",text:"PLO4, PLO5 and PLO6 in numbers"},{type:"table",head:["","PLO4","PLO5","PLO6"],rows:[["Hole cards","4","5","6"],["Two-card combinations","6","10","**15**"],["Seats","up to 9","usually 6","usually 6"],["What wins","Straight, flush","Nut flush, full house","Almost always the nuts"]]},{type:"h2",text:"How a hand plays"},{type:"streets",hole:["A♠","K♠","Q♥","J♥","10♦","9♦"],board:["K♥","Q♠","7♥","9♣","2♥"],opp:["A♥","5♥","K♣","K♦","8♣","3♠"],notes:["Six hole cards give 15 different two-card pairs. The hand is connected and in three suits: spades, hearts and diamonds.","The K♥ Q♠ 7♥ flop gives you **two pair, kings and queens**. In PLO6 opponents often hold hands just as strong, so draws to the nuts matter.","The 9♣: J-10 from your hand and K-Q-9 from the board make **a king-high straight**.","The 2♥ is the third heart. Q♥J♥ from your hand and K♥7♥2♥ from the board make **a king-high flush**. The nut flush would belong to an opponent holding A♥ and another heart.","The opponent shows A♥5♥ — the nut flush, ace high. Your king-high flush loses. In PLO6 second-best hands often pay off."]},{type:"h2",text:"How the game plays"},{type:"ul",items:["**The nuts are everything.** With six cards someone almost always has the best hand; a second-best flush is often a fold.","**Little bluffing, lots of value.** Opponents have something to call with — bet strong hands, check more without them.","**Blockers matter.** Holding the ace of a suit means nobody else has the nut flush in it — useful on the river.","**Run it Multi-Times.** All-ins in PLO6 are often close (55/45), so running the board two or three times is sensible variance insurance.","**Double Board.** PLO6 tables with two boards let you win half the pot even if you lose one board."]},{type:"h2",text:"Which hands to play"},{type:"p",text:"A good PLO6 hand is one where most of the six cards work together: two suits of two or three cards, connected ranks, nut potential (the ace of a suit, top straight cards). A strong example: **A♠K♠Q♥J♥10♦9♦** — three suits, a long rundown, nut flush draws. Weak hands are scattered, unsuited, with gaps."},{type:"h2",text:"Hand rankings"},i,...e("en","PLO6").positions,...e("en","PLO6").pot,{type:"h2",text:"Omaha terms"},{type:"glossary",items:[["2 + 3 rule","Your hand uses exactly two hole cards and three board cards."],["Double-suited","Two pairs of suited cards — two different flush draws."],["Rundown","Connected cards (J-10-9-8) — many straight possibilities."],["Dangler","A card unrelated to the rest of the hand; weakens it."],["Nuts","The best possible hand on the board. In Omaha the nuts usually win."],["Blocker","A card that stops an opponent from holding a hand — e.g. the ace of a suit against the nut flush."],["Pot","The button for a pot-sized bet."]]},...a("en",["ante","double","rim","vpip","gps","bbmax"]),{type:"h2",text:"Where to play PLO6 at MOJO"},{type:"p",text:"PLO6 runs in both clubs from 0.25/0.50 to 5/10, including 10BB and 60BB Max and Double Board tables. If you like action but want to split pots between the best high and the best low, see [Omaha Hi-Lo](/games/plo-hi-lo)."}],faq:[{q:"How many hole cards do I use in PLO6?",a:"Exactly two of your six and exactly three board cards."},{q:"Why is PLO6 usually 6-handed?",a:"Deck size: 7 players × 6 cards + 5 board = 47 cards; with 8 players it is 53 — more than a deck."},{q:"What are the nuts?",a:"The best possible hand on the current board. In PLO6 strong hands are so frequent that the nuts usually win."},{q:"How does Run it Multi-Times help?",a:"On an all-in the remaining cards are dealt 2–3 times and the pot is split by result — less variance."},{q:"Is PLO6 good for beginners?",a:"Start with PLO4: same rules, but mistakes cost more in PLO6 because opponents’ hands are stronger."}]}},{slug:"plo-hi-lo",format:"PLO5 Hi-Lo",formats:["PLO5 Hi-Lo","PLO6 Hi-Lo"],shot:"/images/tables/plo6.webp",clubs:"mu",ru:{menu:"Омаха Hi-Lo",menuDesc:"PLO5 (Big O) и PLO6 Hi-Lo: банк делится между хай и лоу",title:"Омаха Hi-Lo: правила хай-лоу, лоу-рука и примеры раздач",subtitle:"Как в Омахе хай-лоу делится банк, что такое лоу и «восьмёрка или лучше», когда лоу нет, что такое скуп, четвертинка и контрфит. Разборы раздач и отличия PLO5 Hi-Lo (Big O) от PLO6 Hi-Lo.",facts:[["Карт на руках","5 (Big O) или 6"],["Банк","Хай и лоу пополам"],["Лоу","5 разных карт до 8"],["Ставки","Pot-Limit"]],sections:[{type:"p",text:"**Омаха хай-лоу** (Omaha Hi-Lo, Hi/Lo, «восьмёрка или лучше», O8) — это Омаха с разделом банка. На шоудауне банк делится на две половины. Одну забирает лучшая **старшая** рука, как в обычной Омахе. Вторую забирает лучшая **младшая** рука, её называют лоу. Если лоу не собрал никто, весь банк уходит старшей руке."},{type:"p",text:"В клубе MOJO : MU идут два варианта игры. **PLO5 Hi-Lo**, его ещё называют **Big O**, раздаётся с пятью картами на руках. **PLO6 Hi-Lo** раздаётся с шестью. Правила раздела банка у них одинаковые, а отличаются число карт и то, какие руки считаются сильными."},{type:"h2",text:"Правила за минуту"},{type:"ol",items:["Каждый игрок получает 5 карт в PLO5 Hi-Lo или 6 карт в PLO6 Hi-Lo. Ставки пот-лимитные: поставить можно не больше размера банка.","Торговля идёт по тем же улицам, что в холдеме: префлоп, флоп с тремя общими картами, тёрн и ривер.","На шоудауне каждый собирает **сразу две руки**: старшую и младшую. Для каждой берётся **ровно две карты с руки и ровно три с борда**.","Лучшая старшая рука забирает половину банка, лучший лоу забирает вторую половину.","Лоу собирается только из **пяти разных карт не старше восьмёрки**. Если такого лоу нет ни у кого, весь банк получает хай.","Одинаковые руки делят свою половину поровну."]},{type:"h2",text:"Что такое лоу-рука"},{type:"ul",items:["Лоу — это пять карт **разного ранга**, все **не старше восьмёрки**. Туз в лоу считается единицей, а в хай остаётся старшей картой.","Стриты и флеши лоу **не мешают**. Рука A-2-3-4-5 одновременно стрит для хай и лучший возможный лоу.","Пары лоу ломают. Из руки A-A или 2-2 лоу не собрать, нужны две разные низкие карты.","Лоу сравнивают **со старшей карты**, и выигрывает тот, у кого она ниже. 7-5-4-2-A лучше 8-4-3-2-A, потому что семь ниже восьми.","Если старшие карты равны, сравнивают следующие. 7-6-4-3-2 лучше 7-6-5-2-A: на третьей карте четвёрка ниже пятёрки."]},{type:"lows"},{type:"p",text:"Лоу называют по старшей карте: «восьмёрочный», «семёрочный», «шестёрочный». Чем ниже старшая карта, тем сильнее рука, а лучше колеса ничего нет."},{type:"h2",text:"Правило 2 + 3 для обеих половин"},{type:"p",text:"Главное отличие от обычной Омахи: карты для хай и для лоу выбираются **независимо**. В обоих случаях это ровно две карты с руки и три с борда, но пары карт могут быть разными. С рукой A♠2♦K♠K♥Q♣ на борде 3♣ 7♦ 8♠ K♦ J♥ лоу собирается из A-2, получается 8-7-3-2-A. Хай собирается из K-K, и это сет королей."},{type:"cards",cards:["A♠","2♦","K♠","K♥","Q♣"],caption:"A-2 играет в лоу, K-K играет в хай. Это разные пары карт одной руки."},{type:"h3",text:"Частая ошибка: лоу с борда"},{type:"p",text:"Новички часто смотрят только на борд. Даже если на столе лежит A-2-3-4-5, колеса у вас может не быть. С руки всё равно нужно взять **ровно две карты**, обе низкие и другого ранга, чем три карты борда в вашем лоу. С рукой K♠K♥Q♣J♦9♠ на таком борде лоу нет вовсе. С рукой 6♦7♣K♠Q♥J♥ лучший лоу будет 7-6-3-2-A: шестёрка и семёрка с руки плюс A-2-3 с борда."},{type:"h2",text:"Когда лоу нет"},{type:"p",text:"Чтобы лоу вообще был возможен, на борде должно быть **минимум три карты разного ранга от туза до восьмёрки**. Если их меньше, лоу не собирается ни у кого, и **весь банк забирает лучшая старшая рука**."},{type:"table",head:["Борд","Лоу возможен?","Почему"],rows:[["A♣ 4♦ 7♠ K♥ Q♣","Да","Три низкие карты разного ранга: A, 4 и 7"],["3♠ 3♥ 8♦ J♣ K♠","Нет","Низких рангов только два: 3 и 8"],["2♥ 5♣ 6♦ 9♠ 10♥","Да","Три низкие карты: 2, 5 и 6"],["K♦ Q♠ 9♥ 7♣ 2♦","Нет","Низких карт только две, весь банк уходит хай-руке"]]},{type:"h2",text:"Как делится банк: три разбора"},{type:"p",text:"Ниже три раздачи PLO5 Hi-Lo с одинаковым вложением всех игроков. У каждого показаны лучшая старшая и лучшая младшая рука, а под ними видно, кому какая часть банка уходит."},{type:"showdown",title:"Скуп: одна рука забирает всё",board:["A♦","3♣","5♥","9♠","K♦"],players:[{name:"Игрок А",cards:["A♠","2♠","4♦","K♣","Q♦"],high:"стрит до пятёрки",low:"колесо 5-4-3-2-A",win:"Весь банк"},{name:"Игрок Б",cards:["A♣","A♥","K♥","Q♠","J♠"],high:"сет тузов",low:"нет, низкая карта одна"},{name:"Игрок В",cards:["2♦","6♣","7♣","J♥","Q♥"],high:"старшая карта",low:"6-5-3-2-A"}],split:[{label:"Игрок А",pct:100,tone:"high"}]},{type:"p",text:"Двойка и четвёрка игрока А вместе с A-3-5 борда дают стрит до пятёрки, и он бьёт сет тузов. Эти же карты дают колесо, лучший возможный лоу. Игрок А выигрывает обе половины и забирает весь банк. Такой исход называют **скупом** (scoop), и именно к нему стремятся в Hi-Lo."},{type:"showdown",title:"Банк пополам",board:["2♣","6♦","8♠","K♥","K♣"],players:[{name:"Игрок А",cards:["A♠","3♦","9♥","J♣","Q♦"],high:"пара королей",low:"8-6-3-2-A",win:"Лоу · 50%"},{name:"Игрок Б",cards:["K♠","Q♥","Q♠","J♦","10♦"],high:"сет королей",low:"нет низких карт",win:"Хай · 50%"}],split:[{label:"Хай · Игрок Б",pct:50,tone:"high"},{label:"Лоу · Игрок А",pct:50,tone:"low"}]},{type:"p",text:"Сет королей забирает хай, восьмёрочный лоу забирает вторую половину. Каждый получает 50%, и вложенное возвращается обоим."},{type:"showdown",title:"Четвертинка: лоу делится надвое",board:["3♦","4♣","7♠","J♥","Q♣"],players:[{name:"Игрок А",cards:["A♠","2♥","K♠","Q♦","10♠"],high:"пара дам",low:"7-4-3-2-A",win:"Половина лоу · 25%"},{name:"Игрок Б",cards:["A♥","2♦","J♠","J♣","5♥"],high:"сет валетов",low:"7-4-3-2-A",win:"Хай и половина лоу · 75%"}],split:[{label:"Хай · Игрок Б",pct:50,tone:"high"},{label:"Лоу · Б",pct:25,tone:"low"},{label:"Лоу · А",pct:25,tone:"low"}]},{type:"p",text:"У обоих одинаковый лоу 7-4-3-2-A, поэтому лоу-половина делится ещё надвое. Игрок Б забирает хай и четверть банка за лоу, всего 75%. Игроку А остаётся четверть. Это и есть **четвертинка** (quartering): игрок А вложил половину банка, а вернул только четверть, хотя формально «выиграл» лоу."},{type:"h2",text:"Контрфит: когда борд обесценивает ваш лоу"},{type:"streets",hole:["A♠","2♦","K♠","K♥","Q♣"],board:["3♣","4♥","8♦","2♠","J♣"],lo:!0,opp:["A♥","5♣","Q♦","J♠","9♠"],notes:["A-2 — лучшая пара карт для лоу, а пара королей даёт шансы на хай. Но третьей низкой карты в руке нет.","Флоп 3♣ 4♥ 8♦: у вас **натсовый лоу** 8-4-3-2-A и пара королей для хай. Нажмите «Лоу» на столе, чтобы увидеть карты младшей руки.","2♠ — это **контрфит**. Ваш лоу прежний, но соперник с A-5 теперь собирает колесо, а с A-6 получает лоу лучше вашего.","J♣ ничего не меняет: у вас лоу 8-4-3-2-A и пара королей. Против A-5 лоу-половину вы проиграете.","Соперник показывает A♥5♣. С тёрна у него колесо: это и лучший лоу, и стрит до пятёрки для хай. Он забирает весь банк — вот чем опасен контрфит."]},{type:"p",text:"На флопе 3♣ 4♥ 8♦ у руки с A-2 **натсовый лоу** 8-4-3-2-A, лучше на этой доске не собрать. На тёрне выходит 2♠, и всё меняется. Ваш лоу остаётся прежним, но теперь соперник с A-5 на руках собирает колесо, а с A-6 или с пятёркой и шестёркой получает лоу лучше вашего. Карта борда совпала с вашей низкой картой и обесценила её. Это называют **контрфитом** (counterfeit)."},{type:"p",text:"Защита от контрфита — **третья низкая карта** в руке. Будь у вас пятёрка вместо одного из королей, на этом тёрне у вас было бы колесо: A-5 с руки и 2-3-4 с борда. Поэтому руки с тремя низкими картами, например A-2-4 или A-2-5, ценятся выше голого A-2."},{type:"h2",text:"Чем Hi-Lo отличается от обычной Омахи"},{type:"table",head:["","Обычная Омаха","Омаха Hi-Lo"],rows:[["Кто забирает банк","Лучшая старшая рука","Половину берёт старшая рука, половину берёт лоу"],["Лоу","Не играет","Пять разных карт до восьмёрки"],["Если лоу нет","Не бывает","Весь банк уходит старшей руке"],["Ценные карты","Высокие, связанные, одномастные","Тузы, двойки, тройки и одномастный туз"],["Карты 9, 10, J","Хороши для стритов","Слабые: не дают лоу и редко дают натсы"],["Главная цель","Собрать натсы","Скуп, то есть выиграть обе половины"]]},{type:"h2",text:"PLO5 Hi-Lo (Big O) и PLO6 Hi-Lo"},{type:"p",text:"Оба варианта идут в MOJO : MU. Правила лоу и раздела банка у них одинаковые. Но чем больше карт на руках, тем чаще у соперников есть и сильный хай, и хороший лоу. Поэтому в PLO6 Hi-Lo чаще нужны натсы и чаще приходится делить половину банка."},{type:"table",head:["","PLO5 Hi-Lo (Big O)","PLO6 Hi-Lo"],rows:[["Карт на руках","5","6"],["Пар карт с руки для комбинации","10","15"],["Какой лоу обычно выигрывает","Натсовый или второй по силе","Почти всегда только натсовый"],["Лимиты в клубе","от 0.25/0.50 до 1/2","от 0.25/0.50 до 0.50/1"]]},{type:"h3",text:"PLO5 Hi-Lo, или Big O"},{type:"p",text:"Пятикарточную Омаху хай-лоу во многих румах и клубах называют **Big O**. Сильная рука в Big O содержит A-2 или A-3 с ещё одной низкой картой и одномастного туза. Пример такой руки: A♠2♠4♦K♦Q♥. В ней есть два варианта лоу, натсовое флеш-дро и высокие карты для хай."},{type:"h3",text:"PLO6 Hi-Lo"},{type:"p",text:"С шестью картами хорошие руки есть почти у всех, поэтому вторые по силе лоу и средние флеши часто проигрывают. Играйте руки, где есть A-2, запасная низкая карта и натсовые возможности для хай, например A♠2♠3♦5♣K♦Q♥. Разрозненные руки с одной-двумя низкими картами лучше сбрасывать."},{type:"h2",text:"Какие руки играть"},{type:"hands",items:[{t:"Лучшие",d:"A-2 с одной-двумя низкими картами и одномастным тузом. Играют в обе стороны и защищены от контрфита.",cards:["A♠","2♠","3♥","K♥","Q♦"]},{t:"Сильные",d:"A-3 с низкой поддержкой и высокими картами, а также пара тузов с A-2.",cards:["A♦","3♦","4♣","K♠","J♠"]},{t:"Спекулятивные",d:"Низкие связки без туза. Дро на колесо есть, но лоу часто оказывается вторым, а хай слабым.",cards:["2♣","3♦","4♥","5♠","K♣"]},{t:"Слабые",d:"Средние карты без туза. Лоу они не дают и редко собирают натсовый хай.",cards:["8♠","9♠","10♦","J♣","Q♥"]},{t:"Ловушка",d:"Голый A-2 без третьей низкой карты и без масти. С такой рукой легко попасть под контрфит или на четвертинку.",cards:["A♠","2♦","K♣","9♥","7♦"]},{t:"Сильная рука PLO6 Hi-Lo",d:"A-2 с запасными тройкой и пятёркой, одномастный туз и высокие карты для хай.",cards:["A♠","2♠","3♦","5♣","K♦","Q♥"]}]},{type:"h2",text:"Советы для старта"},{type:"ul",items:["Играйте на **скуп**. Рука, которая может выиграть только половину банка, редко стоит больших вложений.","Ищите **натсовый лоу**. Второй по силе лоу в Hi-Lo часто проигрывает или делит половину.","Смотрите на борд. Если на флопе две высокие карты и больше, лоу может не собраться, и всё решит хай.","Если лоу уже невозможен, играйте как в обычную Омаху: весь банк уйдёт старшей руке.","Осторожнее с ре-рейзами, когда у вас только лоу. Банк делится, и вы рискуете получить четверть.","Если Омаха для вас новая, сначала освойте [PLO4](/games/plo4), а потом добавляйте лоу."]},...a("ru",["ante","rim","vpip","gps"]),{type:"h2",text:"Где играть Омаху Hi-Lo"},{type:"p",text:"Столы PLO5 Hi-Lo с лимитами от 0.25/0.50 до 1/2 и PLO6 Hi-Lo с лимитами от 0.25/0.50 до 0.50/1 идут в клубе [MOJO : MU](/clubs/mojo-massiv). В закрытом клубе MOJO : ALLIN Hi-Lo нет, там играют холдем и обычную Омаху."}],faq:[{q:"Что значит Hi-Lo в Омахе?",a:"Банк делится пополам: одна половина уходит лучшей старшей руке, вторая лучшему лоу. Если лоу нет, весь банк забирает старшая рука."},{q:"Что значит «восьмёрка или лучше»?",a:"Лоу считается, только если все пять карт разного ранга и не старше восьмёрки. Восьмёрочный лоу — самый слабый из допустимых."},{q:"Какой лоу лучший?",a:"A-2-3-4-5, его называют колесом. Туз в лоу считается единицей, а стриты и флеши лоу не мешают."},{q:"Сколько карт с руки нужно для лоу?",a:"Ровно две, как и для хай, плюс ровно три с борда. Для хай и для лоу можно брать разные пары карт."},{q:"Что если на борде меньше трёх низких карт?",a:"Тогда лоу невозможен ни у кого, и весь банк уходит лучшей старшей руке."},{q:"Что такое скуп и четвертинка?",a:"Скуп — одна рука выигрывает обе половины банка. Четвертинка — вы делите половину с соперником и получаете четверть банка."},{q:"Что такое Big O?",a:"Так называют PLO5 Hi-Lo, Омаху хай-лоу с пятью картами на руках. В клубе MOJO : MU она идёт вместе с PLO6 Hi-Lo."},{q:"Чем PLO6 Hi-Lo отличается от PLO5 Hi-Lo?",a:"На руках шесть карт вместо пяти, поэтому пар для комбинаций 15 вместо 10. Руки у соперников сильнее, и выигрывают чаще натсовые хай и лоу."},{q:"В каком клубе есть Омаха Hi-Lo?",a:"Только в MOJO : MU. В MOJO : ALLIN Hi-Lo нет."}]},en:{menu:"Omaha Hi-Lo",menuDesc:"PLO5 (Big O) and PLO6 Hi-Lo: the pot splits between high and low",title:"Omaha Hi-Lo: rules, the low hand and worked examples",subtitle:"How the pot splits in Omaha Hi-Lo, what a low and “eight or better” mean, when there is no low, and what scooping, quartering and counterfeiting are. Worked hands and how PLO5 Hi-Lo (Big O) differs from PLO6 Hi-Lo.",facts:[["Hole cards","5 (Big O) or 6"],["Pot","High and low halves"],["Low","5 different cards to 8"],["Betting","Pot-Limit"]],sections:[{type:"p",text:"**Omaha Hi-Lo** (Hi/Lo, “eight or better”, O8) is Omaha with a split pot. At showdown the pot is divided in two. One half goes to the best **high** hand, as in regular Omaha. The other half goes to the best **low** hand. If nobody makes a low, the high hand takes the whole pot."},{type:"p",text:"MOJO : MU runs two versions. **PLO5 Hi-Lo**, also called **Big O**, deals five hole cards. **PLO6 Hi-Lo** deals six. The split-pot rules are the same; the number of cards and which hands are strong are what change."},{type:"h2",text:"The rules in a minute"},{type:"ol",items:["Each player gets 5 cards in PLO5 Hi-Lo or 6 in PLO6 Hi-Lo. Betting is pot-limit: you can bet at most the size of the pot.","Betting follows the Hold’em streets: preflop, the flop with three community cards, the turn and the river.","At showdown everyone makes **two hands at once**, a high and a low. Each uses **exactly two hole cards and exactly three board cards**.","The best high takes half the pot and the best low takes the other half.","A low needs **five different cards, eight or lower**. If nobody has one, the high hand gets the whole pot.","Tied hands share their half equally."]},{type:"h2",text:"What a low hand is"},{type:"ul",items:["A low is five cards of **different ranks**, all **eight or lower**. The ace counts as one for low and stays high for high.","Straights and flushes **do not hurt** a low. A-2-3-4-5 is both a straight for high and the best possible low.","Pairs ruin a low. A-A or 2-2 in your hand cannot make one; you need two different low cards.","Lows are compared **from the top card down**, and the lower top card wins. 7-5-4-2-A beats 8-4-3-2-A because seven is lower than eight.","If the top cards tie, compare the next ones. 7-6-4-3-2 beats 7-6-5-2-A: on the third card, four is lower than five."]},{type:"lows"},{type:"p",text:"A low is named after its top card: an eight-low, a seven-low, a six-low. The lower the top card, the stronger the hand, and nothing beats the wheel."},{type:"h2",text:"The 2 + 3 rule applies to both halves"},{type:"p",text:"The key difference from regular Omaha: you pick cards for high and for low **independently**. Each is exactly two hole cards and three board cards, but the pairs can differ. With A♠2♦K♠K♥Q♣ on a 3♣ 7♦ 8♠ K♦ J♥ board, A-2 makes the low 8-7-3-2-A. K-K makes the high, a set of kings."},{type:"cards",cards:["A♠","2♦","K♠","K♥","Q♣"],caption:"A-2 plays for low and K-K plays for high: two different pairs from one hand."},{type:"h3",text:"A common mistake: the low on the board"},{type:"p",text:"Beginners often read only the board. Even with A-2-3-4-5 on the table you may not have the wheel. You still need **exactly two hole cards**, both low and of different ranks from the three board cards in your low. With K♠K♥Q♣J♦9♠ on that board you have no low at all. With 6♦7♣K♠Q♥J♥ your best low is 7-6-3-2-A: the six and seven from your hand plus A-2-3 from the board."},{type:"h2",text:"When there is no low"},{type:"p",text:"A low is only possible if the board has **at least three different ranks from ace to eight**. With fewer, nobody can make a low and **the best high hand takes the whole pot**."},{type:"table",head:["Board","Low possible?","Why"],rows:[["A♣ 4♦ 7♠ K♥ Q♣","Yes","Three different low ranks: A, 4 and 7"],["3♠ 3♥ 8♦ J♣ K♠","No","Only two low ranks: 3 and 8"],["2♥ 5♣ 6♦ 9♠ 10♥","Yes","Three low cards: 2, 5 and 6"],["K♦ Q♠ 9♥ 7♣ 2♦","No","Only two low cards, so high takes it all"]]},{type:"h2",text:"How the pot splits: three worked hands"},{type:"p",text:"Below are three PLO5 Hi-Lo hands where every player put in the same amount. Each player’s best high and best low are shown, and the bar shows who gets which share of the pot."},{type:"showdown",title:"Scoop: one hand takes it all",board:["A♦","3♣","5♥","9♠","K♦"],players:[{name:"Player A",cards:["A♠","2♠","4♦","K♣","Q♦"],high:"five-high straight",low:"the wheel 5-4-3-2-A",win:"Whole pot"},{name:"Player B",cards:["A♣","A♥","K♥","Q♠","J♠"],high:"set of aces",low:"none, only one low card"},{name:"Player C",cards:["2♦","6♣","7♣","J♥","Q♥"],high:"high card",low:"6-5-3-2-A"}],split:[{label:"Player A",pct:100,tone:"high"}]},{type:"p",text:"Player A’s deuce and four with the A-3-5 on board make a five-high straight, which beats the set of aces. The same cards make the wheel, the best possible low. Player A wins both halves and takes the whole pot. That is a **scoop**, and it is what you play for in Hi-Lo."},{type:"showdown",title:"The pot split in half",board:["2♣","6♦","8♠","K♥","K♣"],players:[{name:"Player A",cards:["A♠","3♦","9♥","J♣","Q♦"],high:"pair of kings",low:"8-6-3-2-A",win:"Low · 50%"},{name:"Player B",cards:["K♠","Q♥","Q♠","J♦","10♦"],high:"set of kings",low:"no low cards",win:"High · 50%"}],split:[{label:"High · Player B",pct:50,tone:"high"},{label:"Low · Player A",pct:50,tone:"low"}]},{type:"p",text:"The set of kings wins high and the eight-low wins the other half. Each player gets 50% and both get their money back."},{type:"showdown",title:"Quartered: the low is split again",board:["3♦","4♣","7♠","J♥","Q♣"],players:[{name:"Player A",cards:["A♠","2♥","K♠","Q♦","10♠"],high:"pair of queens",low:"7-4-3-2-A",win:"Half the low · 25%"},{name:"Player B",cards:["A♥","2♦","J♠","J♣","5♥"],high:"set of jacks",low:"7-4-3-2-A",win:"High and half the low · 75%"}],split:[{label:"High · Player B",pct:50,tone:"high"},{label:"Low · B",pct:25,tone:"low"},{label:"Low · A",pct:25,tone:"low"}]},{type:"p",text:"Both players hold the same 7-4-3-2-A low, so the low half is split again. Player B takes the high plus a quarter for the low, 75% in total. Player A is left with a quarter. That is **quartering**: Player A put in half the pot and got back a quarter, despite “winning” the low."},{type:"h2",text:"Counterfeiting: when the board devalues your low"},{type:"streets",hole:["A♠","2♦","K♠","K♥","Q♣"],board:["3♣","4♥","8♦","2♠","J♣"],lo:!0,opp:["A♥","5♣","Q♦","J♠","9♠"],notes:["A-2 is the best pair of cards for low, and the kings give you chances for high. But there is no third low card.","The 3♣ 4♥ 8♦ flop gives you **the nut low**, 8-4-3-2-A, and a pair of kings for high. Tap “Low” on the table to see the low hand’s cards.","The 2♠ is a **counterfeit**. Your low is unchanged, but an opponent with A-5 now has the wheel, and A-6 beats you too.","The J♣ changes nothing: you have an 8-4-3-2-A low and a pair of kings. Against A-5 you lose the low half.","The opponent shows A♥5♣. Since the turn he has had the wheel: the best low and a five-high straight for high. He scoops the whole pot — that is why counterfeiting hurts."]},{type:"p",text:"On the 3♣ 4♥ 8♦ flop the A-2 holds the **nut low**, 8-4-3-2-A; nothing better is possible on that board. The 2♠ on the turn changes everything. Your low stays the same, but now an opponent with A-5 has the wheel, and A-6, or a five with a six, beats you too. A board card matched your low card and devalued it. This is called **counterfeiting**."},{type:"p",text:"The protection is a **third low card** in your hand. With a five instead of one of the kings, you would have the wheel on that turn: A-5 from your hand and 2-3-4 from the board. That is why hands with three low cards, such as A-2-4 or A-2-5, are worth more than a bare A-2."},{type:"h2",text:"Hi-Lo versus regular Omaha"},{type:"table",head:["","Regular Omaha","Omaha Hi-Lo"],rows:[["Who wins the pot","The best high hand","Half to the best high, half to the best low"],["Low hand","Does not play","Five different cards to eight"],["If there is no low","Not applicable","The high hand takes it all"],["Valuable cards","High, connected, suited","Aces, deuces, treys and a suited ace"],["9, 10, J","Good for straights","Weak: no low and rarely the nuts"],["Main goal","Make the nuts","Scoop, winning both halves"]]},{type:"h2",text:"PLO5 Hi-Lo (Big O) and PLO6 Hi-Lo"},{type:"p",text:"Both versions run in MOJO : MU with the same low and split rules. But the more cards each player holds, the more often opponents have both a strong high and a good low. In PLO6 Hi-Lo you need the nuts more often and split halves more often."},{type:"table",head:["","PLO5 Hi-Lo (Big O)","PLO6 Hi-Lo"],rows:[["Hole cards","5","6"],["Two-card pairs per hand","10","15"],["Low that usually wins","The nut low or the second nuts","Almost always only the nut low"],["Stakes in the club","0.25/0.50 to 1/2","0.25/0.50 to 0.50/1"]]},{type:"h3",text:"PLO5 Hi-Lo, or Big O"},{type:"p",text:"Many rooms and clubs call five-card Omaha Hi-Lo **Big O**. A strong Big O hand holds A-2 or A-3 with another low card and a suited ace, for example A♠2♠4♦K♦Q♥. It has two ways to make a low, a nut flush draw and high cards for the high half."},{type:"h3",text:"PLO6 Hi-Lo"},{type:"p",text:"With six cards almost everyone has a decent hand, so second-best lows and middling flushes often lose. Play hands with A-2, a backup low card and nut potential for high, such as A♠2♠3♦5♣K♦Q♥. Scattered hands with one or two low cards are usually a fold."},{type:"h2",text:"Which hands to play"},{type:"hands",items:[{t:"Best",d:"A-2 with one or two more low cards and a suited ace. These play both ways and are protected against counterfeiting.",cards:["A♠","2♠","3♥","K♥","Q♦"]},{t:"Strong",d:"A-3 with low backup and high cards, and aces with A-2.",cards:["A♦","3♦","4♣","K♠","J♠"]},{t:"Speculative",d:"Low rundowns without an ace. They draw to the wheel, but the low is often second-best and the high is weak.",cards:["2♣","3♦","4♥","5♠","K♣"]},{t:"Weak",d:"Middle cards without an ace. They make no low and rarely the nut high.",cards:["8♠","9♠","10♦","J♣","Q♥"]},{t:"Trap",d:"A bare A-2 with no third low card and no suit. It is easily counterfeited or quartered.",cards:["A♠","2♦","K♣","9♥","7♦"]},{t:"A strong PLO6 Hi-Lo hand",d:"A-2 with a backup three and five, a suited ace and high cards for the high half.",cards:["A♠","2♠","3♦","5♣","K♦","Q♥"]}]},{type:"h2",text:"Starter tips"},{type:"ul",items:["Play to **scoop**. A hand that can only win half the pot rarely justifies a big investment.","Aim for the **nut low**. In Hi-Lo the second-best low often loses or gets split.","Read the board. With two or more high cards on the flop a low may never come, and the high decides everything.","Once a low is impossible, play it like regular Omaha: the whole pot goes to the high hand.","Be careful re-raising with only a low. The pot is split and you risk getting a quarter.","New to Omaha? Learn [PLO4](/games/plo4) first, then add the low."]},...a("en",["ante","rim","vpip","gps"]),{type:"h2",text:"Where to play Omaha Hi-Lo"},{type:"p",text:"PLO5 Hi-Lo from 0.25/0.50 to 1/2 and PLO6 Hi-Lo from 0.25/0.50 to 0.50/1 run in [MOJO : MU](/clubs/mojo-massiv). The private MOJO : ALLIN club has no Hi-Lo; it plays Hold’em and regular Omaha."}],faq:[{q:"What does Hi-Lo mean in Omaha?",a:"The pot is split: half to the best high hand, half to the best low. If there is no low, the high hand takes the whole pot."},{q:"What does “eight or better” mean?",a:"A low only counts if all five cards are different ranks and eight or lower. An eight-low is the weakest qualifying low."},{q:"What is the best low?",a:"A-2-3-4-5, the wheel. The ace counts as one for low, and straights and flushes do not hurt it."},{q:"How many hole cards do I use for the low?",a:"Exactly two, the same as for high, plus exactly three board cards. High and low can use different pairs."},{q:"What if the board has fewer than three low cards?",a:"Then nobody can make a low and the best high hand takes the whole pot."},{q:"What are scooping and quartering?",a:"Scooping is one hand winning both halves. Quartering is splitting one half with an opponent, so you get a quarter of the pot."},{q:"What is Big O?",a:"The common name for PLO5 Hi-Lo, five-card Omaha Hi-Lo. MOJO : MU runs it alongside PLO6 Hi-Lo."},{q:"How is PLO6 Hi-Lo different from PLO5 Hi-Lo?",a:"Six hole cards instead of five, so 15 two-card pairs instead of 10. Opponents hold stronger hands, and the nut high and nut low win more often."},{q:"Which club has Omaha Hi-Lo?",a:"Only MOJO : MU. MOJO : ALLIN has no Hi-Lo."}]}},{slug:"mtt",format:"Multi-Table Tournaments",shot:"/images/tables/mtt.webp",clubs:"both",ru:{menu:"Турниры (MTT)",menuDesc:"Фрироллы, баунти, PKO и сателлиты в клубе",title:"Покерные турниры MTT в клубе: виды, правила и стратегия",subtitle:"Многостоловые турниры в ClubGG — как они устроены, чем отличаются фрироллы, Knockout и Progressive KO, что такое сателлиты и как играть турнир от первой раздачи до финального стола.",facts:[["Формат","MTT"],["Вход","Бесплатно — 150"],["Виды","Фриролл, KO, PKO, сателлит"],["Где","Оба клуба"]],sections:[{type:"p",text:"**Многостоловый турнир (MTT, Multi-Table Tournament)** — турнир, где одновременно играют несколько столов. Все начинают с одинаковым стеком, блайнды растут по уровням, выбывшие игроки освобождают места, а столы постепенно объединяются — до финального стола и победителя. В отличие от кэш-игры, фишки турнира не обмениваются: вы играете на место в итоговой таблице."},{type:"h2",text:"Как устроен турнир"},{type:"ol",items:["**Регистрация.** Записываетесь в лобби турниров. У многих турниров есть поздняя регистрация — можно войти в первые уровни.","**Старт.** Все получают одинаковый стартовый стек — например, 10 000 фишек.","**Уровни блайндов.** Каждые несколько минут блайнды растут, с какого-то уровня добавляется анте. Стеки «уменьшаются» относительно блайндов, и игра ускоряется.","**Пузырь.** Момент перед призовой зоной: следующий выбывший уходит без награды. Игра здесь самая осторожная.","**Призовая зона и финальный стол.** После пузыря все оставшиеся получают награду, финальный стол решает распределение верхних мест."]},{type:"h2",text:"Виды турниров в клубе"},{type:"table",head:["Вид","Как работает","Кому подходит"],rows:[["**Фриролл**","Бесплатный вход, награды для лучших мест","Начать без вложений, освоить турниры"],["**Knockout Bounty (KO)**","За каждого выбитого игрока вы сразу получаете награду за его «голову»","Любителям агрессивной игры"],["**Progressive KO (PKO)**","За выбитого игрока половина баунти идёт вам сразу, половина добавляется к вашей «голове» — она растёт","Тем, кто играет на долгую дистанцию"],["**Сателлит**","Наградой служит билет в более крупный турнир","Попасть в большой турнир с меньшим входом"],["**Freezeout**","Одна жизнь: выбыли — турнир закончен","Классика, понятная структура"]]},{type:"h2",text:"Стратегия по стадиям"},{type:"h3",text:"Ранняя стадия (глубокие стеки)"},{type:"p",text:"Стек большой относительно блайндов, можно играть много рук в позиции и разыгрывать постфлоп. Не рискуйте всем стеком без сильной руки — выжить важнее, чем быстро нарастить фишки."},{type:"h3",text:"Середина (20–40 ББ)"},{type:"p",text:"Появляется анте, банки на префлопе ценнее. Чаще открывайтесь с поздних позиций, воруйте блайнды, используйте рестил (повторный рейз олл-ин) против частых открытий."},{type:"h3",text:"Пузырь и короткий стек (меньше 15 ББ)"},{type:"p",text:"Решения сводятся к «олл-ин или пас». Большие стеки давят на средние, средние стеки избегают рискованных коллов. С коротким стеком ищите первый хороший спот для олл-ина — ждать слишком долго дороже."},{type:"h3",text:"Финальный стол"},{type:"p",text:"Каждое следующее место заметно ценнее предыдущего. Учитывайте стеки соперников: не входите в конфликт с большим стеком без нужды и давите на тех, кто боится вылететь."},{type:"h2",text:"Турнирные термины"},{type:"glossary",items:[["Бай-ин","Стоимость входа в турнир. У фрироллов вход бесплатный."],["Стартовый стек","Количество турнирных фишек, которое получает каждый участник на старте."],["Уровень блайндов","Отрезок времени с фиксированными блайндами; после него блайнды повышаются."],["Поздняя регистрация","Возможность войти в турнир после старта, в первые уровни."],["Ребай / аддон","Докупка фишек: ребай — после вылета или при малом стеке, аддон — один раз в конце периода ребаев."],["Баунти","Награда за выбивание конкретного игрока."],["Пузырь","Последнее место перед призовой зоной."],["ITM (In The Money)","Стадия, когда все оставшиеся игроки уже в призах."],["ICM","Модель, оценивающая ценность турнирного стека с учётом выплат; важна на пузыре и финальном столе."]]},{type:"h2",text:"Как играть турниры в клубах MOJO"},{type:"p",text:"Турниры идут в обоих клубах: фрироллы, Knockout, Progressive KO и мега-сателлиты, вход от бесплатного до 150. Найти их можно во вкладке турниров в лобби клуба ClubGG. Если вы ещё не в клубе — [скачайте ClubGG](/download), [создайте аккаунт](/create-account) и [вступите в MOJO : MU или MOJO : ALLIN](/join). Для своей компании менеджер может создать [закрытый турнир](/poker-with-friends)."}],faq:[{q:"Что такое MTT?",a:"Многостоловый турнир: все стартуют с одинаковым стеком, блайнды растут, столы объединяются до финального."},{q:"Что такое фриролл?",a:"Турнир с бесплатным входом и наградами для лучших мест."},{q:"Чем KO отличается от PKO?",a:"В KO за выбитого игрока вы получаете его баунти целиком. В PKO — половину сразу, а вторая половина добавляется к вашему баунти, и за вашу «голову» дадут больше."},{q:"Что такое сателлит?",a:"Турнир, где наградой служит билет в более крупный турнир."},{q:"Что такое пузырь?",a:"Момент перед призовой зоной, когда следующий выбывший остаётся без награды."},{q:"Можно ли сделать турнир для друзей?",a:"Да, менеджер клуба может создать закрытый турнир с паролем для вашей компании."}]},en:{menu:"Tournaments (MTT)",menuDesc:"Freerolls, bounties, PKO and satellites in the club",title:"MTT poker tournaments in the club: types, rules and strategy",subtitle:"Multi-table tournaments in ClubGG — how they work, freerolls vs Knockout vs Progressive KO, what satellites are and how to play from the first hand to the final table.",facts:[["Format","MTT"],["Entry","Free — 150"],["Types","Freeroll, KO, PKO, satellite"],["Where","Both clubs"]],sections:[{type:"p",text:"A **multi-table tournament (MTT)** runs several tables at once. Everyone starts with the same stack, blinds rise by levels, busted players free up seats and tables merge — down to the final table and a winner. Unlike cash games, tournament chips are not exchanged: you play for a finishing place."},{type:"h2",text:"How a tournament works"},{type:"ol",items:["**Registration.** Register in the tournament lobby. Many events allow late registration during the first levels.","**Start.** Everyone gets the same starting stack — e.g. 10,000 chips.","**Blind levels.** Blinds rise every few minutes, an ante kicks in at some level. Stacks shrink relative to the blinds and play speeds up.","**The bubble.** Just before the paid places: the next player out gets nothing. Play is most cautious here.","**In the money and the final table.** After the bubble everyone left is rewarded; the final table decides the top places."]},{type:"h2",text:"Tournament types in the club"},{type:"table",head:["Type","How it works","Good for"],rows:[["**Freeroll**","Free entry, rewards for the top places","Starting with no investment, learning tournaments"],["**Knockout Bounty (KO)**","You collect a bounty for every player you eliminate","Aggressive players"],["**Progressive KO (PKO)**","Half the bounty is paid at once, half is added to your own bounty, which grows","Long-run players"],["**Satellite**","The reward is a ticket to a bigger tournament","Getting into big events for less"],["**Freezeout**","One life: bust and you are out","Classic, clear structure"]]},{type:"h2",text:"Strategy by stage"},{type:"h3",text:"Early stage (deep stacks)"},{type:"p",text:"Your stack is big relative to the blinds, so you can play more hands in position and outplay postflop. Do not risk your stack without a strong hand — surviving matters more than chipping up fast."},{type:"h3",text:"Middle stage (20–40 BB)"},{type:"p",text:"Antes appear and preflop pots get more valuable. Open more from late position, steal blinds and use resteals (all-in re-raises) against frequent openers."},{type:"h3",text:"Bubble and short stack (under 15 BB)"},{type:"p",text:"Decisions become shove-or-fold. Big stacks pressure the medium ones, medium stacks avoid risky calls. Short-stacked, take the first good spot to shove — waiting too long costs more."},{type:"h3",text:"Final table"},{type:"p",text:"Every next place is worth noticeably more. Watch the stacks: avoid needless clashes with the chip leader and pressure those afraid to bust."},{type:"h2",text:"Tournament terms"},{type:"glossary",items:[["Buy-in","The cost of entering a tournament. Freerolls are free."],["Starting stack","The number of tournament chips each player starts with."],["Blind level","A time period with fixed blinds; blinds rise after it."],["Late registration","Entering a tournament after it starts, during the first levels."],["Rebuy / add-on","Buying more chips: a rebuy after busting or when short, an add-on once at the end of the rebuy period."],["Bounty","A reward for knocking out a specific player."],["Bubble","The last place before the paid places."],["ITM (In The Money)","The stage when everyone left is paid."],["ICM","A model valuing a tournament stack by the payouts; key on the bubble and at the final table."]]},{type:"h2",text:"Playing tournaments at MOJO"},{type:"p",text:"Tournaments run in both clubs: freerolls, Knockout, Progressive KO and mega satellites, entry from free to 150 — find them in the tournaments tab of the club lobby in ClubGG. Not in the club yet? [Download ClubGG](/download), [create an account](/create-account) and [join MOJO : MU or MOJO : ALLIN](/join). For your crew the manager can set up a [private tournament](/poker-with-friends)."}],faq:[{q:"What is an MTT?",a:"A multi-table tournament: everyone starts with the same stack, blinds rise and tables merge down to the final one."},{q:"What is a freeroll?",a:"A tournament with free entry and rewards for the top places."},{q:"How is KO different from PKO?",a:"In KO you collect the whole bounty for a knockout. In PKO you get half at once and the other half is added to your own bounty."},{q:"What is a satellite?",a:"A tournament where the reward is a ticket to a bigger event."},{q:"What is the bubble?",a:"The point just before the paid places, when the next player out gets nothing."},{q:"Can we run a tournament for friends?",a:"Yes, the club manager can create a private password-protected tournament for your group."}]}}],p=o=>d.find(s=>s.slug===o);export{d as G,p as g};
